pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // Fuzz the depositor address and the deposit amount
    function testFuzz_property(address depositor, uint256 amount) public {
        // keep depositor as a plausible EOA and amount within reasonable bounds
        vm.assume(depositor != address(0));
        // bound amount to fit within test environment but allow zero as admissible
        amount = bound(amount, 0, 1 ether);

        // Fund the depositor so they can send Ether
        vm.deal(depositor, amount);

        // Attempt to call receive() from depositor with value `amount`, catching revert
        bool ok;
        vm.prank(depositor);
        try c.call{value: amount}("") {
            // low-level call to c with empty calldata triggers receive/fallback
            ok = true;
        } catch {
            ok = false;
        }

        // The universal property: for the reference contract, any deposit attempt with some value
        // should succeed (ok==true) and the contract's depositsCount should be >= 0 and increased when ok
        // We assert that if amount > 0, the call succeeded (reference accepts deposits of any positive amount).
        // This assertion reads c's behavior via the success boolean (ok) which is true for the reference
        // and false for the mutant for some inputs (e.g., any amount>0).
        assertTrue(amount == 0 || ok);
    }
}

