import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // fuzzed params: depositor (actor) and amount to send
    function testFuzz_property(address depositor, uint256 amount) public {
        // admissible: depositor should be a real address and amount > 0 and fit within balance setup
        vm.assume(depositor != address(0));
        // keep amount in a reasonable range so vm.deal works; still wide
        amount = bound(amount, 1, 1 ether);

        // fund depositor so they can send
        vm.deal(depositor, amount);

        // record pre-state
        uint256 beforeCount = c.depositsCount();
        uint256 beforeBal = address(c).balance;

        // attempt to call receive via low-level send from depositor
        bool ok;
        vm.prank(depositor);
        // we call via payable fallback: send value to contract address
        (bool success, ) = address(c).call{value: amount}("");
        ok = success;

        // After a successful deposit, the reference increments depositsCount and balance increases by amount.
        // The mutant (with strict > check) will revert and thus ok==false for at least some inputs (any amount>0).
        // We assert the universal property: if the call succeeded then depositsCount increased by 1 and balance increased by amount.
        // This is a single assertion reading c's public getters / balance.
        if (ok) {
            assertTrue(
                c.depositsCount() == beforeCount + 1 && address(c).balance == beforeBal + amount
            );
        } else {
            // If call reverted, then the invariant (call succeeds) didn't hold; still assert that c's state didn't change
            // This branch is admissible but the single assert in the function must be executed in all runs.
            // We express a general rule that when call failed, depositsCount and balance remain unchanged.
            assertTrue(c.depositsCount() == beforeCount && address(c).balance == beforeBal);
        }
    }
}

